import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";import"./gzh-BO4QB3XE.js";import"./zsxq-BKcsYlFO.js";var i=JSON.parse(`{"path":"/blog/2022/12month/05-how-to-add-ssh-key-to-github-on-mac.html","title":"如何在 Mac 上为 GitHub 设置 SSH Key（2022）","lang":"zh-CN","frontmatter":{"title":"如何在 Mac 上为 GitHub 设置 SSH Key（2022）","date":"2022-12-18T01:12:01.000Z","author":"小綿尾巴","isOriginal":true,"category":["github"],"tag":["github"],"icon":"mac","sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"description":"SSH(Secure Shell) 是允许两台电脑之间通过安全连接进行数据交换的网络协议。 在本地电脑生成 SSH Key 私钥，再将 SSH Key 公钥添加到 GitHub，就实现了本地电脑和 GitHub 服务器安全连接，可以把本地仓库推送到 GitHub 远程仓库，或把 GitHub 远程仓库拉取到本地仓库，即两台电脑间的数据交换。 Noted...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"如何在 Mac 上为 GitHub 设置 SSH Key（2022）\\",\\"image\\":[\\"https://bornforthis.cn/gzh.jpg\\",\\"https://bornforthis.cn/zsxq.jpg\\"],\\"datePublished\\":\\"2022-12-18T01:12:01.000Z\\",\\"dateModified\\":\\"2025-04-10T23:49:50.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"小綿尾巴\\"}]}"],["meta",{"property":"og:url","content":"https://bornforthis.cn/blog/2022/12month/05-how-to-add-ssh-key-to-github-on-mac.html"}],["meta",{"property":"og:site_name","content":"AI悦创-Python一对一辅导"}],["meta",{"property":"og:title","content":"如何在 Mac 上为 GitHub 设置 SSH Key（2022）"}],["meta",{"property":"og:description","content":"SSH(Secure Shell) 是允许两台电脑之间通过安全连接进行数据交换的网络协议。 在本地电脑生成 SSH Key 私钥，再将 SSH Key 公钥添加到 GitHub，就实现了本地电脑和 GitHub 服务器安全连接，可以把本地仓库推送到 GitHub 远程仓库，或把 GitHub 远程仓库拉取到本地仓库，即两台电脑间的数据交换。 Noted..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://bornforthis.cn/gzh.jpg"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2025-04-10T23:49:50.000Z"}],["meta",{"property":"article:author","content":"小綿尾巴"}],["meta",{"property":"article:tag","content":"github"}],["meta",{"property":"article:published_time","content":"2022-12-18T01:12:01.000Z"}],["meta",{"property":"article:modified_time","content":"2025-04-10T23:49:50.000Z"}]]},"git":{"createdTime":1671297652000,"updatedTime":1744328990000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":5,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":2}],"changelog":[{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"aed1739bbe0401281f8fe9b23c9bcb44b448b9ac","time":1743333691000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"启用编辑链接，提升文档的可用性和用户体验"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"610fee0943c20fde9f54fa74b604beca191c1a25","time":1674624916000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"remove password"},{"hash":"b5c47851b2a7f7bdee883769972153ec019e4916","time":1671335440000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"bce8bfbf845c6c7ef4146152c02c6d1bbd00a7b1","time":1671334675000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"更新为什么写博客"},{"hash":"f92d5ae4cc7d79a93427a664a56fc25869652516","time":1671297652000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"}]},"readingTime":{"minutes":4.71,"words":1412},"filePathRelative":"blog/2022/12month/05-how-to-add-ssh-key-to-github-on-mac.md","excerpt":"<p>SSH(Secure Shell) 是允许两台电脑之间通过安全连接进行数据交换的网络协议。</p>\\n<p>在本地电脑生成 SSH Key 私钥，再将 SSH Key 公钥添加到 GitHub，就实现了本地电脑和 GitHub 服务器安全连接，可以把本地仓库推送到 GitHub 远程仓库，或把 GitHub 远程仓库拉取到本地仓库，即两台电脑间的数据交换。</p>\\n<p><strong>Noted</strong>：GitHub 在 2022 年 5 月添加了 SSH 安全性，以往添加 SSH Key 的教程在有些细节处可能不适用，这是 2022 年下半年添加 SSH Key 的教程。</p>","copyright":{"author":"小綿尾巴"},"autoDesc":true}`),a={name:`05-how-to-add-ssh-key-to-github-on-mac.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<p>SSH(Secure Shell) 是允许两台电脑之间通过安全连接进行数据交换的网络协议。</p><p>在本地电脑生成 SSH Key 私钥，再将 SSH Key 公钥添加到 GitHub，就实现了本地电脑和 GitHub 服务器安全连接，可以把本地仓库推送到 GitHub 远程仓库，或把 GitHub 远程仓库拉取到本地仓库，即两台电脑间的数据交换。</p><p><strong>Noted</strong>：GitHub 在 2022 年 5 月添加了 SSH 安全性，以往添加 SSH Key 的教程在有些细节处可能不适用，这是 2022 年下半年添加 SSH Key 的教程。</p><h2 id="生成-ssh-key" tabindex="-1"><a class="header-anchor" href="#生成-ssh-key"><span>生成 SSH Key</span></a></h2><ol><li>点开 <a href="https://github.com/" target="_blank" rel="noopener noreferrer"> GitHub </a> 账号头像下的 <code>Settings</code></li></ol><figure><img src="/assets/github-setting_hu36b769aebcea935decf2430ed54e8ff5_76796_1320x0_resize_box_3-1332185-DXZjFu6w.png" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><ol start="2"><li>找到 <code>Settings</code> 下的 <code>SSH and GPG keys</code>，点击 <code>generating SSH keys</code>，点击后会打开一个新的页面。</li></ol><figure><img src="/assets/ssh-and-ggp-key_hu131f9c3e0a94150b6fbd34b674d84f78_301129_1320x0_resize_box_3-1332204-Dl9W6C-w.png" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><ol start="3"><li>在新的页面中选择 <code>Generating a new SSH key and adding it to the ssh-agent</code></li></ol><figure><img src="/assets/generating-new-ssh-key_hu4ea39273c16500307782e0fe6449b0a9_264654_1320x0_resize_box_3-1332244-visnLXTH.png" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><ol start="4"><li>注意选择对应操作系统的教程。</li></ol><figure><img src="/assets/mac-ssh-key-guide_hu7f2165d8c95d233ffb38b2487ee336fa_495178_1320x0_resize_box_3-1332265-6yfIczQB.png" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><ol start="5"><li>往下滑动页面会看到 GitHub 给出的 Mac 下生成 SSH Key 的指南，按照指南的步骤一步一步进行。</li></ol><figure><img src="/assets/ssh-key-guide_hu8008dcec60dfe751fd22487158baacd3_564367_1320x0_resize_box_3-1332296-97GVDdXs.png" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><ol start="6"><li>打开终端（Terminal），复制粘贴以下文本到终端，把 <code>your_email@example.com</code> 替换成你注册 GitHub 时使用的邮箱，然后按下Enter键。</li></ol><div class="language-shell line-numbers-mode" data-highlighter="shiki" data-ext="shell" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-shell"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">ssh-keygen</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -t</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> ed25519</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -C</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> &quot;your_email@example.com&quot;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><figure><img src="/assets/terminal-generating-ssh-key_hu1a97a115ba6c4f332978c0a6ba760f65_43360_1320x0_resize_box_3-1332327-6yRVaE15.png" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><ul><li>如果你不记得注册 GitHub 时使用的邮箱，可以从 <code>Settings</code> 中的 <code>Emails</code> 中查看。</li></ul><figure><img src="/assets/github-email_hu3b70f26d446af39e5d0e1c22f35f61fa_339926_1320x0_resize_box_3-1332353-DoZKyJPt.png" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><ol start="7"><li>出现 <code>Enter file in which to save the key(...)</code> ，按下 <code>Enter</code> 键，一直按 <code>Enter</code> 直到出现以下画面。</li></ol><figure><img src="/assets/generate-ssh-key-keep-enter_hufd4be2aa5ec48c535574dce507a9ae22_118260_1320x0_resize_box_3-1332376-DvqyB8a6.png" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><ol start="8"><li>🎉 恭喜你的 SSH Key 已经生成成功，接下来把生成的 SSH Key 添加到 ssh-agent。</li></ol><h2 id="添加-ssh-key-到-ssh-agent" tabindex="-1"><a class="header-anchor" href="#添加-ssh-key-到-ssh-agent"><span>添加 SSH Key 到 ssh-agent</span></a></h2><ol><li>在终端（Terminal）中输入命令：</li></ol><div class="language-shell line-numbers-mode" data-highlighter="shiki" data-ext="shell" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-shell"><span class="line"><span style="--shiki-light:#0184BC;--shiki-dark:#56B6C2;">eval</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> &quot;$(</span><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">ssh-agent</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -s</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;">)&quot;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ul><li>命令执行后终端会给出 <strong>Agent pid</strong></li></ul><ol start="2"><li>如果你使用的是<a href="https://docs.github.com/cn/authentication/connecting-to-github-with-ssh/generating-a-new-ssh-key-and-adding-it-to-the-ssh-agent#adding-your-ssh-key-to-the-ssh-agent" target="_blank" rel="noopener noreferrer"><strong>macOS Siera 10.12.2或以上的版本</strong></a>，你需要修改 <code>~/.ssh/config</code> 文件来自动加载密钥到 ssh-agent 和储存 passphrases 到你的钥匙链。</li></ol><ul><li>首先，检查电脑中是否存在 <code>~/.ssh/config</code> 文件</li></ul><div class="language-shell line-numbers-mode" data-highlighter="shiki" data-ext="shell" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-shell"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">open</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> ~/.ssh/config</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ul><li>如果像我一样显示这个 config 文件不存在，则创建这个文件</li></ul><figure><img src="/assets/check-ssh-config-file_hu851978db82bd99ff6d92eab78df0769c_23446_1320x0_resize_box_3-DhNz9YR7.png" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><div class="language-shell line-numbers-mode" data-highlighter="shiki" data-ext="shell" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-shell"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">touch</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> ~/.ssh/config</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ul><li>用编辑器打开 <code>~/.ssh/config</code> 文件</li></ul><div class="language-shell line-numbers-mode" data-highlighter="shiki" data-ext="shell" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-shell"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">nano</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> ~/.ssh/config</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ul><li>在 nano 窗口中复制粘贴以下代码：</li></ul><div class="language-shell line-numbers-mode" data-highlighter="shiki" data-ext="shell" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-shell"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">Host</span><span style="--shiki-light:#E45649;--shiki-dark:#E5C07B;"> *</span></span>
<span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">	AddKeysToAgent</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> yes</span></span>
<span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">	UseKeychain</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> yes</span></span>
<span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">	IdentityFile</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> ~/.ssh/id_ed25519</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>粘贴代码后按 <code>control+X</code> 退出编辑器</li></ul><figure><img src="/assets/config-ssh-config-file_hu616cea8bc0c34d5b66c0e116fc9053e8_92104_1320x0_resize_box_3-BX6GiEa6.png" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><ul><li>输入 <code>y</code> 保存更改</li></ul><figure><img src="/assets/press-y_hufe205a79243e76590950fae8d2c88cdb_31210_1320x0_resize_box_3-cbBlxSTt.png" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><ul><li>出现这个画面后再按 <code>Enter</code> 键</li></ul><figure><img src="/assets/press-enter_hu5b99bdd9bdcc31b96a41140df1a6d346_33867_1320x0_resize_box_3-BAGfAUc9.png" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><ol start="3"><li>将 SSH Key 添加到 ssh-agent。如果你使用的是<a href="https://docs.github.com/cn/authentication/connecting-to-github-with-ssh/generating-a-new-ssh-key-and-adding-it-to-the-ssh-agent#adding-your-ssh-key-to-the-ssh-agent" target="_blank" rel="noopener noreferrer"><strong>Mac Monterey(12.0)及以上版本</strong></a>，请使用以下命令（<s>因为在Mac Monterey(12.0)及以上版本中，<code>-K</code> 标志已经被废弃，被 <code>--apple-use-keychain</code> 代替</s>）。</li></ol><div class="language-shell line-numbers-mode" data-highlighter="shiki" data-ext="shell" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-shell"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">ssh-add</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> --apple-use-keychain</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> ~/.ssh/id_ed25519</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ul><li>如果不是 Mac Monterey(12.0) 及以上版本，使用以下命令：</li></ul><div class="language-shell line-numbers-mode" data-highlighter="shiki" data-ext="shell" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-shell"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">ssh-add</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -K</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> ~/.ssh/id_ed25519</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ul><li>🎉 出现 <code>Identity added</code> 即表示添加成功。</li></ul><figure><img src="/assets/add-ssh-key-to-ssh-agent_hu61ce29338a356422b81fdf3c1fc34ff7_30427_1320x0_resize_box_3-BuvVu26T.png" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><h2 id="添加-ssh-key-到-github" tabindex="-1"><a class="header-anchor" href="#添加-ssh-key-到-github"><span>添加 SSH Key 到 GitHub</span></a></h2><ol><li>在终端输入以下命令， <code>pbcopy</code> 会复制 SSH Key 内容到剪贴板</li></ol><div class="language-shell line-numbers-mode" data-highlighter="shiki" data-ext="shell" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-shell"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">pbcopy</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> &lt; </span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;">~/.ssh/id_ed25519.pub</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ol start="2"><li>再次打开 GitHub <code>Settings</code> 下的 <code>SSH and GPG Key</code> ，点击 <code>New SSH key</code></li></ol><figure><img src="/assets/new-ssh-key_hu1a0d9f00853f690c7179516d4ccdc015_290032_1320x0_resize_box_3-D9uyWK_K.png" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><ol start="3"><li>添加本机生成的 SSH Key 到 GitHub：</li></ol><ul><li>在 <strong>Title</strong> 中给这个 SSH Key 命名</li><li><strong>Key Type</strong> 选择 <code>Authentication Key</code></li><li>在 <strong>Key</strong> 中 <code>Command+V</code> 粘贴刚刚复制的 SSH Key</li><li>添加后点击</li></ul><figure><img src="/assets/patse-ssh-key_hu353948a22d2b775261070598a993ad44_87805_1320x0_resize_box_3-_zZCr_N3.png" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><ol start="4"><li>🎉 添加完成。</li></ol><h2 id="测试-ssh-key-是否添加成功" tabindex="-1"><a class="header-anchor" href="#测试-ssh-key-是否添加成功"><span>测试 SSH Key 是否添加成功</span></a></h2><ol><li>选择一个要用 SSH Key clone 的仓库，复制这个仓库的 SSH 链接。</li></ol><figure><img src="/assets/ssh-key-repository_hu4350254bf7e39f71438ec987d67bd4fc_224398_1320x0_resize_box_3-DZevBIaA.png" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><ol start="2"><li>在终端输入:</li></ol><div class="language-shell line-numbers-mode" data-highlighter="shiki" data-ext="shell" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-shell"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">git</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> clone</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> [ssh-url]</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><figure><img src="/assets/add-ssh-repository_hu02fc432d195bb76f6116cfdff780d462_81382_1320x0_resize_box_3-CY9vxzP0.png" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><ol><li>🎉 clone 成功即代表 SSH Key 添加成功。</li></ol><h2 id="reference" tabindex="-1"><a class="header-anchor" href="#reference"><span>Reference</span></a></h2><ul><li><a href="https://www.youtube.com/watch?v=_RsP81Et12s" target="_blank" rel="noopener noreferrer">How to Set Up an SSH Key to GitHub on Mac</a></li></ul><p>欢迎关注我公众号：AI悦创，有更多更好玩的等你发现！</p><details class="hint-container details"><summary>公众号：AI悦创【二维码】</summary><figure><img src="/gzh.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure></details><div class="hint-container info"><p class="hint-container-title">AI悦创·编程一对一</p><p>AI悦创·推出辅导班啦，包括「Python 语言辅导班、C++ 辅导班、java 辅导班、算法/数据结构辅导班、少儿编程、pygame 游戏开发、Linux、」，全部都是一对一教学：一对一辅导 + 一对一答疑 + 布置作业 + 项目实践等。当然，还有线下线上摄影课程、Photoshop、Premiere 一对一教学、QQ、微信在线，随时响应！微信：Jiabcdefh</p><p>C++ 信息奥赛题解，长期更新！长期招收一对一中小学信息奥赛集训，莆田、厦门地区有机会线下上门，其他地区线上。微信：Jiabcdefh</p><p>方法一：<a href="http://wpa.qq.com/msgrd?v=3&amp;uin=1432803776&amp;site=qq&amp;menu=yes" target="_blank" rel="noopener noreferrer">QQ</a></p><p>方法二：微信：Jiabcdefh</p></div><figure><img src="/zsxq.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure>`,70)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};